import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
import {evaluateCareerEvidence} from '../scripts/ufc-36-month-stage3-progress.mjs';
const read=n=>JSON.parse(readFileSync(new URL('../data/'+n,import.meta.url),'utf8'));
const roster=read('ufc-36-month-roster-approval.json'),census=read('ufc-36-month-candidates.json'),profiles=read('ufcalendar-fighter-research.json').profiles,cache=read('ufcalendar-rich-progress.json'),reg=read('ufc-independent-full-career-verification.json').fighters;
const cases={'jhonata-diniz':['182','84120'],'jose-delgado':['436','83991'],'mansur-abdul-malik':['359','83988'],'navajo-stirling':['116','88273']};
const hist=s=>profiles[s].recentHistory.filter(h=>h.source==='native'&&h.promotion==='ufc'&&h.boutId&&!/contender series|road to ufc|\bdwcs\b/i.test(cache.bouts[h.boutId]?.event||''));
const check=(s,x)=>evaluateCareerEvidence(profiles[s],hist(s),census.fighters.find(f=>f.slug===s).lastUfcFight,roster.rosterAsOf,x,cache.bouts).independentlyVerified;
test('wave86 four complete six-bout UFC histories preserve 24 exact independent source IDs, original corners, measured rounds, one draw and DWCS exclusions',()=>{
assert.equal(roster.approvedFighters.length,783);const sourceUrls=new Set();
for(const [s,[id,feeder]] of Object.entries(cases)){const x=reg[s];assert.ok(roster.approvedFighters.includes(s));assert.equal(x.sourceCoverageAttested,true);assert.equal(x.scope,'complete_official_ufc_career');assert.equal(x.officialUfcCareerBoutCount,6);assert.equal(x.bouts.length,6);assert.equal(hist(s).length,6);assert.deepEqual(x.verifiedNumericFighterIds,[id]);assert.equal(x.sourceSnapshot.fightResultsBlobSha,'699c9b6cebb542bf458807563d93ed2406d8728f');
for(const f of x.bouts){assert.match(f.fightUrl,/^https:\/\/ufcstats\.com\/fight-details\/[a-f0-9]{16}$/);assert.equal(sourceUrls.has(f.fightUrl),false);sourceUrls.add(f.fightUrl);const b=cache.bouts[f.nativeBoutId];assert.equal(b.org,'ufc');assert.ok(Number(cache.roundDone[f.nativeBoutId])>0);assert.ok(Math.abs(Date.parse(b.eventDate)-Date.parse(f.date))<=86400000);const own=b.a.id===id?b.a:b.b.id===id?b.b:null;assert.ok(own);assert.equal(own.slug,s);const other=own===b.a?b.b:b.a;assert.equal(other.name,f.opponent);const outcome=b.status==='draw'||(!b.result?.winnerId&&b.result?.method==='draw')?'draw':b.result?.winnerId===own.id?'win':b.result?.winnerId===other.id?'loss':null;assert.equal(outcome,f.result)}
assert.equal(x.sourceVerifiedExcludedFeederBouts.length,1);assert.equal(x.sourceVerifiedExcludedFeederBouts[0].nativeBoutId,feeder);assert.match(cache.bouts[feeder].event,/contender series/i);assert.ok(!x.bouts.some(b=>b.nativeBoutId===feeder));assert.equal(check(s,x),true,s+' complete strict Stage3 pass')}
assert.equal(sourceUrls.size,24);assert.ok(reg['mansur-abdul-malik'].bouts.some(b=>b.result==='draw'));assert.ok(reg['navajo-stirling'].bouts.some(b=>b.date==='2024-12-15'&&b.opponent==='Tuco Tokkos'));
});
test('wave86 missing UFC bout, fabricated native ID, inverted outcome and repeated Greco URL fail closed',()=>{for(const s of Object.keys(cases)){const x=reg[s];assert.equal(check(s,{...x,bouts:x.bouts.slice(1)}),false);assert.equal(check(s,{...x,verifiedNumericFighterIds:['999999']}),false);assert.equal(check(s,{...x,bouts:x.bouts.map((b,i)=>i?b:{...b,result:b.result==='win'?'loss':'win'})}),false);assert.equal(check(s,{...x,bouts:x.bouts.map((b,i)=>i?b:{...b,fightUrl:x.bouts[1].fightUrl})}),false)}});

